import{_ as o,c as r,ag as e,o as t}from"./chunks/framework.-a8jReyC.js";const m=JSON.parse('{"title":"Importação de Faturas","description":"","frontmatter":{"title":"Importação de Faturas"},"headers":[],"relativePath":"features/import-transactions.md","filePath":"features/import-transactions.md"}'),s={name:"features/import-transactions.md"};function i(n,a,c,l,u,p){return t(),r("div",null,a[0]||(a[0]=[e('<h1 id="📥-importacao-de-faturas-pdf-ofx" tabindex="-1">📥 Importação de Faturas (PDF/OFX) <a class="header-anchor" href="#📥-importacao-de-faturas-pdf-ofx" aria-label="Permalink to &quot;📥 Importação de Faturas (PDF/OFX)&quot;">​</a></h1><p>A importação de faturas é uma das formas mais rápidas de colocar seu controle financeiro em dia. Em vez de digitar cada compra manualmente, você anexa o arquivo da fatura do seu cartão de crédito e o FlyCash faz o resto.</p><h2 id="o-que-a-importacao-faz" tabindex="-1">O que a importação faz <a class="header-anchor" href="#o-que-a-importacao-faz" aria-label="Permalink to &quot;O que a importação faz&quot;">​</a></h2><ul><li><strong>Lê o arquivo da fatura</strong> nos formatos <strong>PDF</strong> ou <strong>OFX</strong>.</li><li><strong>Extrai as transações</strong> automaticamente, com data, descrição e valor.</li><li><strong>Sugere categorias</strong> para cada compra (você pode ajustar antes de confirmar).</li><li><strong>Aponta possíveis duplicatas</strong>, para você não registrar a mesma compra duas vezes.</li><li><strong>Reconhece parcelas</strong> (ex: &quot;3/10&quot;) e as projeta nas próximas faturas.</li></ul><h2 id="como-importar" tabindex="-1">Como importar <a class="header-anchor" href="#como-importar" aria-label="Permalink to &quot;Como importar&quot;">​</a></h2><ol><li><strong>Baixe o arquivo da fatura</strong> no app do seu banco (procure por &quot;exportar&quot; ou &quot;extrato em PDF/OFX&quot;).</li><li>No FlyCash, abra a janela de <strong>Importar Transações</strong> (módulo de transações).</li><li><strong>Arraste o arquivo</strong> ou clique para selecionar (<code>fatura.pdf</code> ou <code>fatura.ofx</code>).</li><li><strong>Revise as transações</strong> que entraram: confira datas, valores, categorias e duplicatas.</li><li>Clique em <strong>Importar</strong> para confirmar.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>O OFX é o formato de arquivo de extrato bancário. Se o seu banco não oferecer, use o PDF da fatura.</p></div><h2 id="deteccao-de-duplicatas" tabindex="-1">Detecção de duplicatas <a class="header-anchor" href="#deteccao-de-duplicatas" aria-label="Permalink to &quot;Detecção de duplicatas&quot;">​</a></h2><p>Ao importar, o FlyCash compara cada transação com as que já existem no seu controle:</p><ul><li>Se encontrar uma duplicata provável, ela vem <strong>desmarcada</strong> e com um aviso para você revisar.</li><li>Caso a detecção automática não encontre, você pode <strong>buscar manualmente</strong> uma possível duplicata e associá-la antes de importar — evitando registros repetidos.</li></ul><h2 id="parcelas-e-projecao" tabindex="-1">Parcelas e projeção <a class="header-anchor" href="#parcelas-e-projecao" aria-label="Permalink to &quot;Parcelas e projeção&quot;">​</a></h2><p>Compras parceladas são reconhecidas automaticamente (ex: &quot;Parcela 3/10&quot;). O FlyCash:</p><ul><li>Mantém a parcela na descrição para você acompanhar.</li><li>Configura a <strong>recorrência</strong> das parcelas restantes, projetando-as nas próximas faturas.</li></ul><h2 id="dicas" tabindex="-1">Dicas <a class="header-anchor" href="#dicas" aria-label="Permalink to &quot;Dicas&quot;">​</a></h2><ul><li>Importe a fatura <strong>logo após o fechamento</strong> para ter o controle mais atualizado.</li><li>Revise as <strong>categorias sugeridas</strong> — o sistema aprende com seus ajustes.</li><li>Fique atento ao <strong>limite de importações do seu plano</strong> (veja <a href="/plans-and-pricing.html">Planos e Preços</a>).</li></ul><hr><p>A importação é especialmente útil para quem usa cartão de crédito com frequência. Combine com o <a href="/features/transactions.html">registro manual</a> para ter um controle completo: o que você paga na hora é anotado na hora, e o que vai para a fatura entra automaticamente.</p>',17)]))}const f=o(s,[["render",i]]);export{m as __pageData,f as default};
